import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"14、【大有】 乾下離上","description":"周易口訣義 - 14、【大有】 乾下離上","frontmatter":{"title":"14、【大有】 乾下離上","description":"周易口訣義 - 14、【大有】 乾下離上"},"headers":[],"relativePath":"classics/koujueyi/016.md","filePath":"classics/koujueyi/016.md"}'),r={name:"classics/koujueyi/016.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_14、【大有】-乾下離上" tabindex="-1">14、【大有】 乾下離上 <a class="header-anchor" href="#_14、【大有】-乾下離上" aria-label="Permalink to “14、【大有】 乾下離上”">​</a></h1><p>彖曰：「大有」，柔得尊位，大中而上下應之，曰「大有」。其德剛健而文明，應乎天而時行，是以「元亨」。</p><p>象曰：火在天上，「大有」。君子以遏惡揚善，順天休命。</p><p>初九，無交害，匪咎，艱則無咎。</p><p>象曰：大有初九，無交害也。</p><p>九二，大車以載，有攸往，無咎。</p><p>象曰：「大車以載」，積中不敗也。</p><p>九三，公用亨於天子，小人弗克。</p><p>象曰：「公用亨於天子」，小人害也。</p><p>九四，匪其彭，無咎。象曰：「匪其彭無咎」，明辨晳也。</p><p>六五，厥孚交如威如，吉。</p><p>象曰：「厥孚交如」，信以發志也。威如之吉，易而無備也。</p><p>上九，自天祐之，吉無不利。</p><p>象曰：大有上吉，「自天祐」也。</p><p>解讀</p><p>大有元亨者，柔處尊位，不拒於物，群陽並應，大為所有，故稱「大有」。故老子云：「江海所以能為百谷王者，以其善下也。」元亨者，能包容萬物，則大得亨通也。</p><p>象曰「火在天上，大有，君子以遏惡揚善，順天休命」者，火是日，如日在天上，無所不照，無遠不燭，是「大有」之象也。君子當須遏匿人之過惡，稱揚人之德善，又須順天之道，休美萬物之性命，是好生惡殺之義也。</p><p>「初九無交害匪咎，艱則無咎」者，處大有之初，不能履中謙柔，必至驕盈陵物，故戒之：即日雖無交切之害，後必將至，若欲免其兇咎，當須艱固不盈，即得「無咎」也。</p><p>「九二，大車以載，有攸往，無咎」者，以剛居中而應於五，為君委任，即是持正之臣，任重專權，猶如大車，所載非少，體既剛強，不懼傾敗，謂車材強壯，以斯而往，何咎之有？故曰「大車以載，有攸往，無咎」也。</p><p>「九三，公用亨於天子，小人弗克」者，公謂臣之貴極也；九三以剛健盛極，權臣之象也。若以賢良處之，即得亨於天子，助化之道也；若以小人處之，禍害立至，故曰「小人弗克」也。</p><p>「九四，匪其彭，無咎」者，彭，旁也，謂去三之旁而從於君也。九四逼近九三，三是權臣，威權之盛，所以九四欲舍九五而從九三，舍君事臣，違於常理。若能棄三旁而歸於五，即得「無咎」也。</p><p>六五，厥孚交如，威如，吉者，以柔處尊，志又弘大，體柔即和順於物，居中即所納不遺，群賢悉歸，信接於下，故不言之化而教自行，不令之威而人皆服，自然獲吉，何難何防？任之得人，故易而無備矣。</p><p>上九「自天祐之，吉，無不利」者，居「大有」之時而不履位，尚賢也。餘皆乘剛，而上九獨乘柔，順思順也。五有信德而親比焉，是履信也。有此三德，故從天以下皆祐助之而得其吉，無所不利也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
